<script setup lang="ts">
import {plotTickLabel} from '../../platform/plotTicks.ts';
import ModuleWorkbench from '../../components/ModuleWorkbench.vue';
import {computed,ref,reactive,watch,onMounted,onUnmounted,markRaw} from 'vue';
import type {ResearchContext,ResearchFile,JobView} from '../../platform/research.ts';
import {workspace,host} from '../../state/workspace.ts';
import {stop} from '../../state/audio.ts';
import {decodeWav} from '../../platform/decode.ts';
import ModuleFrame from '../../components/ModuleFrame.vue';
import ModuleToolbar from '../../components/ModuleToolbar.vue';
import ModuleSection from '../../components/ModuleSection.vue';
import ModuleStatus from '../../components/ModuleStatus.vue';
import ModalDialog from '../../components/ModalDialog.vue';
import WaveformViewport from '../../components/WaveformViewport.vue';
import AudioTransport from '../../components/AudioTransport.vue';
import TaskPanel from '../../components/TaskPanel.vue';
import {defaults,generationDefaults,labels,kinds,designs,clone,validate,validatePoints,table,current,type Points,type Analysis} from './state.ts';
import {downloadM07,messages,type M07Result,type Settings} from '../../platform/m07.ts';
const props=defineProps<{context:ResearchContext;stateKey:string;active:boolean}>();const emit=defineEmits<{references:[]}>();
const analysis=reactive(defaults()),generation=reactive(generationDefaults()),alignment=ref<'normalize'|'onset'>('normalize'),count=ref(21),kind=ref<1|2|3>(2),reverse=ref(false);
const wave=workspace(props.stateKey),sourceWave=workspace(props.stateKey+'.source'),targetWave=workspace(props.stateKey+'.target');
const files=ref<ResearchFile[]>([]),source=ref<ResearchFile>(),target=ref<ResearchFile>(),directory=ref(''),output=ref(''),outputLabel=ref(''),picker=ref<HTMLInputElement>();
const error=ref(''),notice=ref(''),busy=ref(false),help=ref(false),applied=ref<M07Result>(),points=ref<Points>({axis:[],source:[],target:[]}),pending=ref(false),analysisIdentity=ref('');
const jobs=ref<JobView[]>([]),results=ref<M07Result[]>([]),selected=ref<M07Result>(),playName=ref(''),batchSummary=ref('');
const inputEpoch={source:0,target:0};
let restoredDraft:{sourceHash?:string;targetHash?:string;analysisHash?:string;points:Points;alignment:string;count:number}|undefined;
let epoch=0,selectionEpoch=0,disposed=false,abort:AbortController|undefined,currentJob:string|undefined;
const port=computed(()=>props.context.files.m07);
const identity=computed(()=>JSON.stringify([source.value?.id,source.value?.sha256,target.value?.id,target.value?.sha256,analysis]));
const stale=computed(()=>!!applied.value&&analysisIdentity.value!==identity.value);
const ready=computed(()=>!!applied.value&&!stale.value&&!pending.value&&!busy.value);
const taskRows=computed(()=>jobs.value.map(j=>({id:j.id,title:'发声连续统 · '+j.id.slice(0,8),status:j.state,progress:j.progress,error:messages[j.error_code??'']??j.error_code??undefined,canCancel:['queued','running','cancel_requested'].includes(j.state)})));
const numericKeys=Object.keys(labels) as (keyof Analysis)[];
watch(analysis,()=>{wave.dirty=true;stop();},{deep:true,flush:'sync'});
watch(generation,()=>{wave.dirty=true;stop();},{deep:true,flush:'sync'});
watch([alignment,count],()=>{wave.dirty=true;pending.value=true;stop();void attempt(()=>rebuild());});
watch([kind,reverse],()=>{wave.dirty=true;stop();});
watch(()=>props.active,v=>{if(!v)stop();});
function report(e:unknown){error.value=e instanceof Error?(messages[e.message]??e.message):String(e);}
async function attempt(work:()=>unknown|Promise<unknown>,valid=()=>true){error.value='';try{await work();}catch(e){if(!disposed&&valid())report(e);}}
function updateJob(job:JobView){const i=jobs.value.findIndex(j=>j.id===job.id);if(i>=0)jobs.value[i]=job;else jobs.value.unshift(job);currentJob=job.id;}
async function refresh(){files.value=(await props.context.files.list(directory.value||undefined)).filter(f=>/\.wav$/i.test(f.name));}
async function choose(){await attempt(async()=>{const grant=await props.context.files.choose?.('input');if(grant){directory.value=grant.id;await refresh();}});}
async function add(event:Event){await attempt(async()=>{const el=event.target as HTMLInputElement;props.context.files.add?.([...el.files??[]]);el.value='';await refresh();});}
async function chooseOutput(){await attempt(async()=>{const grant=await props.context.files.choose?.('output');if(grant){output.value=grant.id;outputLabel.value=grant.label;}});}
async function select(role:'source'|'target',id:string){
 const file=files.value.find(f=>f.id===id);if(role==='source')source.value=file;else target.value=file;
 wave.dirty=true;stop();const ticket=++inputEpoch[role];selectionEpoch++;epoch++;abort?.abort();busy.value=false;
 const w=role==='source'?sourceWave:targetWave;w.asset=null;
 if(!file)return;
 await attempt(async()=>{const data=await props.context.files.read(file);const asset=await decodeWav(data.buffer,file.name);if(disposed||ticket!==inputEpoch[role]||(role==='source'?source.value:target.value)?.id!==id)return;if(asset.duration>10)throw Error('当前 M07 输入限 10 秒');file.sha256=data.sha256;w.asset=markRaw(asset);w.start=0;w.end=asset.duration;w.zoom=1;w.offset=0;},()=>ticket===inputEpoch[role]);
}
function rebuild(){if(applied.value)points.value=table(applied.value.metadata.source_f0,applied.value.metadata.target_f0,count.value,alignment.value);}
function edit(role:'source'|'target',i:number,event:Event){const text=(event.target as HTMLInputElement).value;points.value[role][i]=text.trim()===''?0:Number(text);pending.value=true;wave.dirty=true;stop();}
function settings(action:Settings['action']):Settings{return {schema_version:'m07/1',batch_group_count:1,batch_group_index:0,action,analysis:clone(analysis),generation:clone(generation),alignment:alignment.value,point_count:count.value,continuum_type:kind.value,reverse_direction:reverse.value,analysis_job_id:action==='analyze'?null:applied.value?.job,controls:action==='apply'?validatePoints(clone(points.value)):null};}
async function run(action:'analyze'|'apply'){
 await attempt(async()=>{
  if(busy.value)return;if(!port.value||!source.value||!target.value)throw Error('请先选择源音频和目标音频，并使用可用的任务宿主');validate(analysis,generation);
  if(action==='apply'&&(!applied.value||stale.value))throw Error('分析已失效，请重新提取 F0');
  const config=settings(action),ticket=++epoch,revision=identity.value;abort=new AbortController();busy.value=true;wave.dirty=true;stop();
  try{const result=await port.value.run(source.value,target.value,config,abort.signal,j=>{if(ticket===epoch&&!disposed)updateJob(j);});
   if(disposed||!current(ticket,epoch,revision,identity.value)){if(ticket===epoch)notice.value='输入或分析参数已改变，迟到分析未应用';return;}
   applied.value=result;analysisIdentity.value=identity.value;points.value=clone(result.metadata.controls);pending.value=false;notice.value=action==='analyze'?'分析完成，控制点尚未修改':'F0 编辑已应用，LPC、残差和脉冲继续复用';
   if(action==='analyze'&&restoredDraft&&restoredDraft.sourceHash===source.value?.sha256&&restoredDraft.targetHash===target.value?.sha256&&restoredDraft.alignment===alignment.value&&restoredDraft.count===count.value&&restoredDraft.analysisHash===JSON.stringify(analysis)){points.value=clone(restoredDraft.points);pending.value=true;restoredDraft=undefined;notice.value='已重新分析相同输入，并恢复草稿控制点，请显式应用编辑';}
  }catch(e){if(ticket===epoch&&!disposed)throw e;}finally{if(ticket===epoch)busy.value=false;}
 });
}
async function generate(all=false){
 await attempt(async()=>{
  if(!ready.value||!port.value||!source.value||!target.value)throw Error(pending.value?'请先应用控制点编辑':stale.value?'分析已失效，请重新提取 F0':'请先完成分析');validate(analysis,generation);
  const snapshot=settings('generate'),sourceFile=clone(source.value),targetFile=clone(target.value),plan=all?designs():[{kind:kind.value,reverse:reverse.value}],batch=crypto.randomUUID();
  const ticket=++epoch;abort=new AbortController();const signal=abort.signal;busy.value=true;wave.dirty=true;stop();let complete=0;batchSummary.value=`0 / ${plan.length} 组完成`;
  try{for(const design of plan){
   if(signal.aborted||ticket!==epoch)break;
   const result=await port.value.run(sourceFile,targetFile,{...snapshot,batch_id:batch,batch_group_count:plan.length===6?6:1,batch_group_index:complete,continuum_type:design.kind,reverse_direction:design.reverse},signal,j=>{if(ticket===epoch&&!disposed)updateJob(j);});
   if(disposed||ticket!==epoch)return;
   if(!results.value.some(r=>r.job===result.job))results.value.unshift(result);complete++;batchSummary.value=`${complete} / ${plan.length} 组完成`;
  }notice.value=complete===plan.length?'生成完成，试听和保存绑定各组已应用快照':'生成已停止，完整组保留';
  }catch(e){if(ticket===epoch&&!disposed)throw e;}finally{if(ticket===epoch){busy.value=false;if(complete<plan.length)batchSummary.value=`部分完成：${complete} / ${plan.length} 组，其余未完成或未提交`;}}
 });
}
async function cancel(id=currentJob){abort?.abort();if(id&&port.value)await attempt(()=>port.value!.cancel(id));}
async function loadHistory(){await attempt(async()=>{if(!port.value)return;const ticket=epoch;const history=await port.value.list();if(disposed||ticket!==epoch)return;jobs.value=history;for(const job of history.filter(j=>j.state==='succeeded')){const result=await port.value.result(job);if(disposed||ticket!==epoch)return;if(result.metadata.action==='generate'&&!results.value.some(r=>r.job===job.id))results.value.push(result);}notice.value='已读取正式任务历史。未提交的组不会被当作成功';});}
async function retry(job:JobView){await attempt(async()=>{if(busy.value||!port.value)return;updateJob(await port.value.retry(job.id));notice.value='已提交重试，请刷新历史查看结果';});}
async function play(result:M07Result,name:string){const ticket=++selectionEpoch;await attempt(async()=>{stop();const raw=await port.value!.read(result,name);const asset=await decodeWav(raw,name);if(disposed||ticket!==selectionEpoch)return;selected.value=result;playName.value=name;wave.asset=markRaw(asset);wave.start=0;wave.end=asset.duration;wave.zoom=1;wave.offset=0;notice.value='已载入本组音频，请点击播放选区';},()=>ticket===selectionEpoch);}
async function download(result:M07Result,name:string){const ticket=epoch;await attempt(async()=>{downloadM07(await port.value!.read(result,name),name);if(ticket===epoch)notice.value='文件已交给浏览器下载';},()=>ticket===epoch);}
async function saveResult(result:M07Result){const ticket=epoch;await attempt(async()=>{if(props.context.files.kind==='desktop'&&!output.value){await chooseOutput();if(!output.value)return;}await port.value!.save(result,output.value);if(ticket===epoch)notice.value='已保存本组完整文件和参数清单';},()=>ticket===epoch);}
function save(){try{if(busy.value)throw Error('任务仍在进行，请先完成或取消');validate(analysis,generation);if(points.value.axis.length)validatePoints(points.value);const draft={sourceHash:applied.value?.metadata.inputs.source.sha256??restoredDraft?.sourceHash,targetHash:applied.value?.metadata.inputs.target.sha256??restoredDraft?.targetHash,analysisHash:applied.value?JSON.stringify(applied.value.metadata.analysis):restoredDraft?.analysisHash,analysis:clone(analysis),generation:clone(generation),alignment:alignment.value,count:count.value,kind:kind.value,reverse:reverse.value,points:clone(points.value),pending:pending.value};if(!host.projects.write('m07.draft.'+props.stateKey,draft))throw Error('草稿保存失败');wave.dirty=false;notice.value='参数和未应用控制点已保存为草稿';return true;}catch(e){report(e);return false;}}
defineExpose({save});
const plotMax=computed(()=>Math.max(50,Math.ceil(Math.max(...[...points.value.source,...points.value.target].filter(Number.isFinite),0)/50)*50));
const f0Svg=ref<SVGSVGElement>(),f0Width=ref(600),f0Height=ref(260);let f0Observer:ResizeObserver|undefined;
watch(f0Svg,el=>{f0Observer?.disconnect();if(el){f0Observer=new ResizeObserver(e=>{f0Width.value=e[0].contentRect.width;f0Height.value=e[0].contentRect.height});f0Observer.observe(el)}});onUnmounted(()=>f0Observer?.disconnect());
function path(values:number[]){const max=Math.max(1,...points.value.axis);return values.map((v,i)=>`${i?'L':'M'}${50+points.value.axis[i]/max*(f0Width.value-70)},${f0Height.value-35-(Number.isFinite(v)?v:0)/plotMax.value*(f0Height.value-65)}`).join(' ');}
onMounted(()=>{const draft=host.projects.read<{sourceHash?:string;targetHash?:string;analysisHash?:string;analysis:Analysis;generation:ReturnType<typeof generationDefaults>;alignment:'normalize'|'onset';count:number;kind:1|2|3;reverse:boolean;points:Points;pending:boolean}|null>('m07.draft.'+props.stateKey,null);if(draft){try{validate(draft.analysis,draft.generation);Object.assign(analysis,draft.analysis);Object.assign(generation,draft.generation);alignment.value=draft.alignment;count.value=draft.count;kind.value=draft.kind;reverse.value=draft.reverse;points.value=draft.points;restoredDraft=draft;pending.value=!!draft.points.axis.length;notice.value='已恢复参数草稿。重新选择输入并分析后才能应用旧控制点';wave.dirty=false;}catch(e){report(e);}}void attempt(refresh);});
onUnmounted(()=>{disposed=true;epoch++;selectionEpoch++;abort?.abort();stop();sourceWave.asset=null;targetWave.asset=null;});
</script>
<template><ModuleFrame unified fit label="发声类型连续统工作区" class="m07-page" :aria-busy="busy">
<template #toolbar><ModuleToolbar><button class="primary" v-if="context.files.choose" @click="choose">打开音频目录</button><button class="primary" v-else-if="context.files.add" @click="picker?.click()">添加 WAV</button><button @click="attempt(refresh)">刷新文件</button><input ref="picker" hidden type="file" accept=".wav" multiple @change="add"/><button v-if="context.files.choose" @click="chooseOutput">输出位置</button><span>{{outputLabel||(context.files.kind==='server'?'项目受管结果 · 下载保存':'尚未选择输出位置')}}</span><template #actions><button @click="save">保存参数草稿</button><button @click="help=true">参数帮助</button><button @click="emit('references')">方法与来源</button></template></ModuleToolbar></template>

<ModuleWorkbench unified :state-key="stateKey" left-label="F0 数值表" center-label="基频曲线对比" right-label="连续统与任务"><template #left><ModuleSection label="输入音频" class="source-selectors"><div v-for="role in ['source','target'] as const" :key="role"><label>{{role==='source'?'源音频':'目标音频'}}<select :aria-label="role==='source'?'源音频':'目标音频'" :value="(role==='source'?source:target)?.id??''" @change="select(role,($event.target as HTMLSelectElement).value)"><option value="">请选择 WAV</option><option v-for="file in files" :key="file.id" :value="file.id">{{file.name}}</option></select></label></div></ModuleSection><ModuleSection label="分析参数"><div class="controls"><label>F0 后端<select v-model="analysis.f0_backend" aria-label="F0 后端"><option value="parselmouth">Parselmouth / Praat</option><option value="reaper">REAPER</option></select></label><label v-for="key in numericKeys.slice(0,3)" :key="key">{{labels[key]}}<input v-model.number="analysis[key]" type="number" step="any" :aria-label="labels[key]"/></label><button class="primary" :disabled="busy||!port||!source||!target||!sourceWave.asset||!targetWave.asset" @click="run('analyze')">提取 F0</button><span>目标采样率 11025 Hz</span></div><details><summary>高级分析参数</summary><div class="controls"><label v-for="key in numericKeys.slice(3)" :key="key">{{labels[key]}}<input v-model.number="analysis[key]" type="number" step="any" :aria-label="labels[key]"/></label><label>窗函数<select v-model="analysis.window_name"><option v-for="name in ['hamming','hann','blackman','rectangular']" :key="name">{{name}}</option></select></label><label class="check"><input v-model="analysis.trim_silence" type="checkbox"/>静音裁剪</label></div></details></ModuleSection>
<div class="controls"><label>F0 对齐<select v-model="alignment" aria-label="F0 对齐" :disabled="busy"><option value="normalize">归一化有声时长</option><option value="onset">起点对齐</option></select></label><label>F0 控制点数量<input v-model.number="count" type="number" min="20" max="200" aria-label="F0 控制点数量" :disabled="busy"/></label><button class="primary" :disabled="busy||!applied||stale" @click="run('apply')">应用编辑</button><button :disabled="!applied||pending||stale" @click="download(applied!,'edited_f0.csv')">保存 F0 CSV</button></div><div class="table-scroll"><table v-if="points.axis.length"><thead><tr><th>{{alignment==='normalize'?'对齐时间 (%)':'对齐时间 (ms)'}}</th><th>源 F0 (Hz)</th><th>目标 F0 (Hz)</th></tr></thead><tbody><tr v-for="(x,i) in points.axis" :key="i"><td>{{x.toFixed(3)}}</td><td v-for="role in ['source','target'] as const" :key="role"><input :value="points[role][i]===0?'':points[role][i]" :aria-label="`${role==='source'?'源':'目标'} F0 第 ${i+1} 点`" :disabled="busy" @input="edit(role,i,$event)"/></td></tr></tbody></table><ModuleStatus v-else kind="empty" message="完成分析后显示 F0。编辑需显式应用，生成不会自动混入未应用值。"/></div></template><div class="input-pair"><ModuleSection v-for="role in ['source','target'] as const" :key="role" :label="role==='source'?'源音频':'目标音频'" :title="role==='source'?'源音频':'目标音频'"><WaveformViewport v-if="(role==='source'?sourceWave:targetWave).asset" :state="role==='source'?sourceWave:targetWave" auto-amplitude compact-overview continuous-detail/><ModuleStatus v-else kind="empty" message="选择音频后显示实际波形"/><AudioTransport :state="role==='source'?sourceWave:targetWave" :active="active" compact/></ModuleSection></div>
<ModuleSection label="基频曲线对比" class="main-f0"><svg v-if="points.axis.length" ref="f0Svg" :viewBox="`0 0 ${f0Width} ${f0Height}`" role="img" aria-label="源与目标 F0 对照" class="f0-plot"><path :d="`M50,30 V${f0Height-35} H${f0Width-20}`" class="axis"/><text x="32" y="16">F0 (Hz)，显示 0–{{plotMax}}</text><text :x="f0Width/2" :y="f0Height-5" text-anchor="middle">{{alignment==='normalize'?'归一化有声时间 (%)':'有声起点后时间 (ms)'}}</text><g v-for="tick in 5" :key="tick"><text x="44" :y="f0Height-30-(tick-1)*(f0Height-65)/4" text-anchor="end">{{plotTickLabel((tick-1)*plotMax/4)}}</text><text :x="50+(tick-1)*(f0Width-70)/4" :y="f0Height-18" text-anchor="middle">{{plotTickLabel((tick-1)*Math.max(1,...points.axis)/4)}}</text></g><path :d="path(points.source)" class="source-line"/><path :d="path(points.target)" class="target-line"/></svg><div v-if="points.axis.length" class="legend">实线：源 F0 · 虚线：目标 F0 · {{pending?'正在编辑':'分析/已应用控制点'}}</div></ModuleSection><template #right><ModuleStatus v-if="error" kind="error" :message="error"/><ModuleStatus v-if="stale" kind="info" message="输入或分析参数已改变，原分析失效，请重新提取 F0。已生成结果保持原快照。"/><ModuleStatus v-if="pending" kind="info" message="控制点或对齐方式有未应用修改，请点击应用编辑。"/><ModuleStatus v-if="notice" kind="info" :message="notice"/><ModuleStatus v-if="!port" kind="info" message="当前宿主未提供 M07 任务能力。请选择已验证的 Windows 工作台，网页计算需通过平台准入。"/><ModuleSection label="连续统与幅度"><div class="parameter-stack"><label>连续统类型<select v-model.number="kind" aria-label="连续统类型"><option v-for="(label,id) in kinds" :key="id" :value="Number(id)">{{label}}</option></select></label><label>合成方向<select v-model="reverse" aria-label="合成方向"><option :value="false">源到目标</option><option :value="true">目标到源</option></select></label><label>连续统步数<input v-model.number="generation.step_count" type="number" min="2" max="50" aria-label="连续统步数"/></label><label class="check"><input v-model="generation.energy_match" type="checkbox"/>周期能量匹配</label><label class="check"><input v-model="generation.normalize_to_source" type="checkbox"/>输出响度匹配源音频</label><label>输出峰值限制<input v-model.number="generation.output_peak_limit" type="number" step="0.01" min="0.01" max="1"/></label><button class="primary" :disabled="!ready||!port" @click="generate(false)">生成当前</button><button class="primary" :disabled="!ready||!port" @click="generate(true)">生成全部六组</button><button :disabled="!busy" @click="cancel()">取消任务</button><p>全部：三种类型 × 两个方向，每组 {{generation.step_count}} 步。使用当前对齐方式和已应用轨迹。</p><p>{{batchSummary}}</p></div></ModuleSection><details class="task-results"><summary>任务与结果（{{results.length}} 组）</summary><ModuleSection label="任务与结果"><button @click="loadHistory">刷新任务历史</button><TaskPanel :tasks="taskRows" empty-title="暂无任务" empty-text="分析与生成分别进入受控工作进程" @cancel="cancel"/><div v-for="job in jobs.filter(j=>['failed','cancelled','interrupted'].includes(j.state))" :key="job.id"><button :disabled="busy" @click="retry(job)">重试 {{job.id.slice(0,8)}}</button></div><div v-for="result in results" :key="result.job" class="result-row"><strong>{{result.metadata.reverse_direction?'目标到源':'源到目标'}} · {{kinds[result.metadata.continuum_type]}} · {{result.metadata.generation.step_count}} 步</strong><span>完整成功 · {{result.job.slice(0,8)}} · 批次 {{result.metadata.batch_id?.slice(0,8)}} 第 {{(result.metadata.batch_group_index??0)+1}} / {{result.metadata.batch_group_count??1}} 组 · 分析 {{result.metadata.analysis_job_id?.slice(0,8)}}</span><div class="controls"><button v-for="f in result.files.filter(f=>f.name.endsWith('.wav')).sort((a,b)=>a.name.localeCompare(b.name))" :key="f.id" @click="play(result,f.name)">{{f.name==='combined_steps.wav'?'整组试听':f.name.replace('.wav','')}}</button><button class="primary" @click="saveResult(result)">{{context.files.kind==='desktop'?'保存完整组':'下载完整组'}}</button><button @click="download(result,'m07.ptb.json')">参数与结果清单</button></div></div><p v-if="selected">当前试听：{{selected.metadata.reverse_direction?'目标到源':'源到目标'}} · {{kinds[selected.metadata.continuum_type]}} · {{playName}} · 参数归属 {{selected.job.slice(0,8)}}</p><WaveformViewport v-if="wave.asset" :state="wave" auto-amplitude continuous-detail/><AudioTransport :state="wave" :active="active" compact/></ModuleSection>
</details></template></ModuleWorkbench><ModalDialog v-if="help" title="发声类型连续统参数帮助" @close="help=false"><p>源与目标 WAV → 提取 F0 → 编辑并应用控制点 → 生成当前或六组 → 试听与保存。输入目前限每份 10 秒、480,000 帧及 8 MB。桌面无需登录，网页输入和结果受项目权限与额度控制。</p><p>原音频 F0 确定 LPC 分析区间，残差 F0 用于脉冲与连续统。F0 提取间隔以毫秒计，内部轨迹为 1 ms 网格，LPC 帧长和帧移以采样点计。编辑 F0 继续使用原 LPC、残差和脉冲。</p><p>归一化对齐把有声时长映射到 0–100%，起点对齐保留各自时长。合成沿用原方法，将目标有效 F0 重采样到源分析区间。CSV 保存完整 1 ms 源/目标轨迹，空白控制点按无声值处理，内部有效点间插值规则与原实现一致。</p><p>周期能量匹配实际匹配目标残差周期的绝对峰值，输出响度匹配实际匹配全段平均绝对振幅，两个开关独立。峰值限制在重合成后逐步应用。结果端点仍受当前方向的源声道滤波和幅度处理影响。</p><p>每组原子发布，全部六组逐组执行。取消或失败后完整组保留，刷新历史可找回。生成后更改参数不会修改已有结果，试听与导出始终读取该组快照。保存时使用独立组目录，不覆盖旧成果。</p><p>该方法是 LPC 残差操纵得到的实验刺激，不表示还原声门生理机制，也未证明发声类别知觉效度或步长知觉等距。来源包括载瓦语相关研究及继承 Python 实现，论文与代码许可分别登记。音标示例 <span class="ipa-text">a̤ a̰</span> 使用公共 Doulos SIL 字体。</p></ModalDialog>
</ModuleFrame></template>
